/**
 * 车厢按编号去重并规范化升序（自然序）。
 */
private List<String> normalizeCars(List<String> cars) {
    return cars.stream().collect(java.util.stream.Collectors.toCollection(TreeSet::new))
            .stream().toList();
}

/**
 * 计算计划编组在停靠站台上的占用时段：取该计划占用清单的整体包络 [最早开始, 最晚结束)。
 */
private Instant[] occupancyEnvelope(List<Occupancy> occupancies) {
    Instant start = occupancies.stream().map(Occupancy::startUtc).min(Instant::compareTo)
            .orElseThrow(() -> badRequest("计划缺少区段占用，无法进行站台复核"));
    Instant end = occupancies.stream().map(Occupancy::endUtc).max(Instant::compareTo)
            .orElseThrow(() -> badRequest("计划缺少区段占用，无法进行站台复核"));
    return new Instant[]{start, end};
}

